import{_ as n,l as s,o as e,c as i,v as o,p as l,x as t,d as c,i as A,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"规模报酬对规模经济","description":"","frontmatter":{"title":"规模报酬对规模经济","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/returns-vs-economies.md","filePath":"econ/returns-vs-economies.md","lastUpdated":1789023840000}'),p={name:"econ/returns-vs-economies.md"};function m(d,a,C,h,_,u){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=o('<h1 id="规模报酬对规模经济" tabindex="-1">规模报酬对规模经济 <a class="header-anchor" href="#规模报酬对规模经济" aria-label="Permalink to &quot;规模报酬对规模经济&quot;">​</a></h1><div class="epigraph"><p>规模报酬是生产集的锥性质；规模经济是成本函数的次加性。把二者写成同一句话，自然垄断与竞争供给都会接错。</p><footer>—— 据 Varian, Microeconomic Analysis；Baumol, On the Proper Cost Tests for Natural Monopoly, AER, 1977 整理</footer></div><p>定位：<a href="/econ/sunk-cost">上一课</a>。短长期把 \\(c_{\\mathrm{SR}}\\) 与包络 \\(c_{\\mathrm{LR}}\\) 钉死，停产看 AVC。本课不重讲沉没与包络切点。<a href="/econ/production-technology">技术</a>已定义 CRS/IRS/DRS 为 \\(Y\\) 的锥，<a href="/econ/cost-minimization">成本最小化</a>已给出 \\(c(w,q)\\)。缺口是后课市场结构会混用两套语言：技术一次齐次，并不等于平均成本下降，更不等于「一家生产更省」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规模报酬问的是：若 \\(y\\in Y\\)，则 \\(\\lambda y\\) 是否仍在 \\(Y\\)。它不看要素价格。规模经济问的是既定 \\(w\\) 下，把产量捆在一起是否比拆开更便宜。单产出时常见写法是 AC 随 \\(q\\) 下降；严格的产业组织用法是<strong>次加性</strong>：</p> \\[c(w,q_1+q_2)\\le c(w,q_1)+c(w,q_2). \\]<p>缺口不是再画一条 U 形 AC，而是：<strong>齐次性推不出次加性，次加性也不回推齐次性。</strong> 要素价格一变，同一套 \\(f\\) 的成本形状可以翻面。上一课的长期包络是「给定 \\(w\\) 选 \\(z_f\\)」，本课在包络上再问：这条 \\(c_{\\mathrm{LR}}(w,\\cdot)\\) 对产量可不可加。</p><h3 id="下降的-ac-只是次加性的特例" tabindex="-1">下降的 AC 只是次加性的特例 <a class="header-anchor" href="#下降的-ac-只是次加性的特例" aria-label="Permalink to &quot;下降的 AC 只是次加性的特例&quot;">​</a></h3><p>AC 递减 \\(\\Rightarrow\\) 次加性，反过来不必：多产出时一种产品的 AC 上升，仍可能整体次加（范围经济）。Baumol 把自然垄断的成本检验写成次加性，而不是「IRS」三个字母。后课<a href="/econ/natural-monopoly-ramsey">自然垄断</a>默认读的是成本侧，不读锥。</p><p><span class="marginnote">一次齐次的 \\(f\\) 加固定要素价格，给出 \\(c(w,q)=q\\,c(w,1)\\)，MC\\(=\\)AC，谈不上下降的 AC。IRS 常让 AC 下降，但 \\(w\\) 随行业扩张而涨时，局部均衡的 AC 可以不降——那是外部不经济，不是把 DRS 写进 \\(f\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写技术：单产出 \\(f\\) 为 \\(k\\) 次齐次，则 CRS 当 \\(k=1\\)。再写成本：在 \\(w\\) 冻住时把 \\(c(w,q)\\) 对 \\(q\\) 求导，读 MC 与 AC 的相对位置。比较必须声明 \\(w\\) 是否内生。行业扩张抬高专用要素价格，单家看起来 DRS，其实是外部成本，<a href="/econ/perfect-competition">完全竞争</a>的长期供给倾斜正用这一层。</p><p>次加性是全局陈述，U 形 AC 只在有效规模左侧局部下降。一家工厂过了有效规模之后，复制第二家可能更省——次加性破裂，自然垄断消失。检验对象是整条成本，不是某一点的切线。</p>',13)),(e(),l(E,null,{default:t(()=>[A(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y%5B%22%E6%8A%80%E6%9C%AF%20Y%EF%BC%9A%E9%94%A5%E4%B8%8E%E9%BD%90%E6%AC%A1%22%5D%20--%3E%20RS%5B%22%E8%A7%84%E6%A8%A1%E6%8A%A5%E9%85%AC%EF%BC%9A%CE%BBy%20%E6%98%AF%E5%90%A6%E5%8F%AF%E8%A1%8C%22%5D%0A%20%20C%5B%22%E6%88%90%E6%9C%AC%20c(w%2Cq)%22%5D%20--%3E%20SUB%5B%22%E6%AC%A1%E5%8A%A0%E6%80%A7%EF%BC%9A%E5%90%88%E4%BA%A7%E6%98%AF%E5%90%A6%E6%9B%B4%E7%9C%81%22%5D%0A%20%20RS%20--%3E%20GAP%5B%22%E4%BA%8C%E8%80%85%E4%B8%8D%E7%9B%B8%E7%AD%89%22%5D%0A%20%20SUB%20--%3E%20GAP%0A%20%20GAP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BF%9B%E5%85%A5%E3%80%81%E8%87%AA%E7%84%B6%E5%9E%84%E6%96%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>本课仍是单家、价格接受。\\(w\\) 当参数。不要把次加性写成限价簿深度「合在一起更厚」——簿是量化栏，这里没有报价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>齐次性进入成本的机制是：投入按比例放大、产出按 \\(k\\) 次放大，要素账单同步放大，于是 \\(c\\) 对 \\(q\\) 的次数被 \\(k\\) 钉住。次加性的机制可以完全不同：共享的不可分设备、一次沉没的管网，使两份产量分摊同一笔 \\(z_f\\)。上一课刚把沉没从短期 MC 里拿掉；那笔沉没摊进长期 AC 之后，正是规模经济最常见的来源——<strong>成本会计</strong>，不是锥。</p><p>反过来：技术 IRS 但要素市场向上倾斜，\\(w(q)\\) 上升可以抵消物理上的节省，观测到的 AC 不必降。故「看见下降的 AC」既不能断定 \\(f\\) 齐次，也不能断定进入之后只该留一家；还要问 \\(w\\) 从哪来。</p><p>多产出时必须回到向量次加性，不能按每种产品的 AC 分别检验。铁路的客运与货运共享路网，分产品 AC 可能都上升，合产仍更省——这正是 Baumol 强调「对自然垄断做成本检验要用整条 \\(c(q)\\)」的原因。后课自然垄断读的是这一全局陈述，不是某一条下降的平均成本曲线。</p><p><span class="marginnote">范围经济是 \\(c(q_1,q_2)\\lt c(q_1,0)+c(0,q_2)\\)，与规模经济并列，同属次加性家族。不要把多产品次加写成霍特林选址，也不要写成订单簿的合并。Varian 教材把 returns to scale 与 economies of scale 分章对照，本课沿这条刀。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>学习曲线、动态 IRS、网络效应会让「本期 \\(c(q)\\)」不再是静态函数，次加性要改成跨期。规制用 AC 还是用增量成本做准入检验，是自然垄断课的对象。本课不引入可竞争性、不引入 Ramsey。</p><p>也不要把规模经济写成 CAPM 的规模因子或权重量化——那是别的栏。后课默认：说到「规模报酬」指 \\(Y\\) 的锥；说到「规模经济 / 次加性」指 \\(c(w,\\cdot)\\)。市场结构先进入价格接受的加总，再用次加性决定要不要只留一家。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>规模报酬是技术齐次；规模经济是成本次加。二者不可互换。</li><li>AC 下降只是次加性的常见特例；要素价格内生可以拆掉这层表象。</li><li>沉没的共享投入是成本侧规模经济的典型来源，不是把 IRS 再写一遍。</li><li>下一课把短、长期供给推进价格接受的市场加总。</li><li>出处：Varian, <em>Microeconomic Analysis</em>；Baumol, <em>AER</em>, 1977；Mas-Colell, Whinston and Green 第 5 章。</li></ul>',11))])}const q=n(p,[["render",m]]);export{B as __pageData,q as default};
